sections.css:
*{margin:0;padding:0;box-sizing:border-box}
body{background:#0f172a;color:#e2e8f0;font-family:'Segoe UI',Tahoma,sans-serif;display:flex;justify-content:center;padding:10px;min-height:100vh}
.container{max-width:720px;width:100%;margin:0 auto}
h1{text-align:center;font-size:15px;color:#fbbf24;margin-bottom:4px}
h2{text-align:center;font-size:11px;color:#64748b;margin-bottom:6px;font-weight:400}
.canvas-wrap{background:#0f172a;border:1px solid #334155;border-radius:8px;padding:4px;margin-bottom:6px}
canvas#mainCanvas{display:block;margin:0 auto;width:100%;max-width:700px;height:340px}
.controls{display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;background:#1e293b;border-radius:8px;padding:8px;border:1px solid #334155}
.ctrl-group{display:flex;flex-direction:column;gap:2px}
.ctrl-group label{font-size:10px;color:#94a3b8}
.ctrl-group .val{color:#fbbf24;font-size:11px;font-weight:700}
input[type=range]{width:100%;height:4px;-webkit-appearance:none;background:#334155;border-radius:2px;outline:none}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:14px;height:14px;border-radius:50%;background:#f59e0b;cursor:pointer}
.full{grid-column:1/-1}
.mode-group{display:flex;gap:4px}
.mode-btn{flex:1;background:#334155;color:#94a3b8;border:1px solid #475569;border-radius:4px;padding:4px;font-size:10px;cursor:pointer;text-align:center;transition:all .15s}
.mode-btn.active{background:#3b82f6;color:#fff;border-color:#3b82f6;font-weight:700}
.info-row{display:flex;gap:8px;justify-content:center;margin-top:4px;font-size:11px;color:#94a3b8;flex-wrap:wrap}
.info-row span{background:#1e293b;padding:3px 8px;border-radius:4px;border:1px solid #334155}
.info-row .hl{color:#fbbf24;font-weight:700}
.info-row .val{font-weight:700}
.f0-val{color:#22c55e;font-weight:700}
.imax-val{color:#ef4444;font-weight:700}
.df-val{color:#8b5cf6;font-weight:700}
.q-val{color:#3b82f6;font-weight:700}
@media(max-width:550px){.controls{grid-template-columns:1fr 1fr}}

sections.js:
const canvas=document.getElementById('mainCanvas'),ctx=canvas.getContext('2d');
const W=700,H=340;
const rS=document.getElementById('rSlider'),lS=document.getElementById('lSlider'),cS=document.getElementById('cSlider'),uS=document.getElementById('uSlider'),fS=document.getElementById('fSlider');
const speedBtns=document.querySelectorAll('#speedGroup .mode-btn');
const viewBtns=document.querySelectorAll('[data-view]');
const playFreqBtn=document.getElementById('playFreqBtn'),playTimeBtn=document.getElementById('playTimeBtn'),resetBtn=document.getElementById('resetBtn');
const rVal=document.getElementById('rVal'),lVal=document.getElementById('lVal'),cVal=document.getElementById('cVal'),uVal=document.getElementById('uVal'),fVal=document.getElementById('fVal');
const f0D=document.getElementById('f0Display'),iMaxD=document.getElementById('imaxDisplay'),dfD=document.getElementById('dfDisplay'),qD=document.getElementById('qDisplay'),phiD=document.getElementById('phiDisplay'),phiSpan=document.getElementById('phiSpan'),fLabel=document.getElementById('fLabel'),phiMaxD=document.getElementById('phiMaxD'),phaseModeSpan=document.getElementById('phaseModeSpan');
let isSweeping=false,speed=1,viewMode='i',timeAnim=null,timePlaying=false;
let simQ=0,simI=0,simT=0,dt=5e-6;
let qHist=[],iHist=[],tHist=[],uHist=[],maxHist=500;
function compute(R,L,C,U,f){const w=2*Math.PI*f;const Z=Math.sqrt(R*R+(w*L-1/(w*C))**2);return{Z,I:Z>0?U/Z:U/R}}
function params(R,L,C,U){const w0=1/Math.sqrt(L*C),f0=w0/(2*Math.PI),Im=U/R,Q=(1/R)*Math.sqrt(L/C),df=f0/Q;return{w0,f0,Im,Q,df}}
function curve(R,L,C,U,fS,fE,n){const pts=[];for(let i=0;i<=n;i++){const f=fS+(i/n)*(fE-fS);const{Z,I}=compute(R,L,C,U,f);pts.push({f,Z,I})}return pts}
function phiCircuit(R,L,C,f){const w=2*Math.PI*f;const w0=1/Math.sqrt(L*C);if(w<1e-9)return 0;return Math.atan2(w*L-1/(w*C),R)*180/Math.PI}
function freqData(R,L,C,U,fS,fE,n){const pts=[];for(let i=0;i<=n;i++){const f=fS+(i/n)*(fE-fS);const{Z,I}=compute(R,L,C,U,f);const ph=phiCircuit(R,L,C,f);pts.push({f,Z,I,ph})}return pts}
function drawPhi(){
  const R=+rS.value,L=+lS.value,C=+cS.value*1e-6,U=+uS.value,freq=+fS.value;
  rVal.textContent=R;lVal.textContent=L.toFixed(2);cVal.textContent=(C*1e6).toFixed(0);uVal.textContent=U;fVal.textContent=freq.toFixed(1);
  const{f0,Im,Q,df}=params(R,L,C,U);f0D.textContent=f0.toFixed(1);iMaxD.textContent=Im.toFixed(3);dfD.textContent=df.toFixed(1);qD.textContent=Q.toFixed(2);
  phiSpan.style.display='none';phaseModeSpan.style.display='inline';
  const fMax=Math.max(200,f0*3),data=freqData(R,L,C,U,1,fMax,150);
  ctx.clearRect(0,0,W,H);ctx.fillStyle='#0f172a';ctx.fillRect(0,0,W,H);
  const pd={t:12,r:40,b:28,l:50},pw=W-pd.l-pd.r,ph=H-pd.t-pd.b;
  ctx.fillStyle='#1e293b';ctx.fillRect(pd.l,pd.t,pw,ph);
  const maxPhi=90,minPhi=-90;
  const toX=f=>pd.l+(f/fMax)*pw,toY=phv=>pd.t+ph-(phv-minPhi)/(maxPhi-minPhi)*ph;
  ctx.strokeStyle='#334155';ctx.lineWidth=0.5;
  for(let i=0;i<=4;i++){const y=pd.t+(i/4)*ph;ctx.beginPath();ctx.moveTo(pd.l,y);ctx.lineTo(pd.l+pw,y);ctx.stroke()}
  for(let i=1;i<=4;i++){const x=pd.l+(i/4)*pw;ctx.beginPath();ctx.moveTo(x,pd.t);ctx.lineTo(x,pd.t+ph);ctx.stroke()}
  ctx.fillStyle='#64748b';ctx.font='8px sans-serif';ctx.textAlign='right';
  for(let i=0;i<=4;i++){const lbl=(90-i*180/4).toFixed(0);ctx.fillText(lbl+'°',pd.l-4,pd.t+(i/4)*ph+3)}
  ctx.textAlign='center';
  for(let i=1;i<=4;i++){const x=pd.l+(i/4)*pw;ctx.fillText((fMax*i/4).toFixed(0),x,pd.t+ph+14)}
  ctx.fillStyle='#64748b';ctx.font='9px sans-serif';ctx.textAlign='center';ctx.fillText('f (Hz)',pd.l+pw/2,H-4);
  ctx.save();ctx.translate(12,pd.t+ph/2);ctx.rotate(-Math.PI/2);ctx.textAlign='center';ctx.fillText('φ (°)',0,0);ctx.restore();
  // φ=0 reference line
  const y0=toY(0);ctx.strokeStyle='rgba(34,197,94,0.5)';ctx.lineWidth=1;ctx.setLineDash([4,3]);ctx.beginPath();ctx.moveTo(pd.l,y0);ctx.lineTo(pd.l+pw,y0);ctx.stroke();ctx.setLineDash([]);
  ctx.fillStyle='#22c55e';ctx.font='7px sans-serif';ctx.textAlign='left';ctx.fillText('φ=0',pd.l+2,y0-3);
  // φ curve
  ctx.strokeStyle='#f59e0b';ctx.lineWidth=2.5;ctx.beginPath();
  for(let i=0;i<data.length;i++){const x=toX(data[i].f),y=toY(data[i].ph);i===0?ctx.moveTo(x,y):ctx.lineTo(x,y)}ctx.stroke();
  // f0 marker
  ctx.strokeStyle='#22c55e';ctx.lineWidth=1;ctx.setLineDash([4,2]);ctx.beginPath();const f0x=toX(f0);ctx.moveTo(f0x,pd.t);ctx.lineTo(f0x,pd.t+ph);ctx.stroke();ctx.setLineDash([]);
  ctx.fillStyle='#22c55e';ctx.font='bold 9px sans-serif';ctx.textAlign='center';ctx.fillText('f₀='+f0.toFixed(1)+' Hz',f0x,pd.t-4);
  // cursor
  const cx=toX(freq),cy=toY(phiCircuit(R,L,C,freq));ctx.fillStyle='#fbbf24';ctx.beginPath();ctx.arc(cx,cy,4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fbbf24';ctx.font='8px sans-serif';ctx.textAlign='center';ctx.fillText(freq.toFixed(1)+' Hz',cx,pd.t+ph+5);
  phiMaxD.textContent=(90).toFixed(0);
}
function drawFreq(){
  const R=+rS.value,L=+lS.value,C=+cS.value*1e-6,U=+uS.value,freq=+fS.value;
  rVal.textContent=R;lVal.textContent=L.toFixed(2);cVal.textContent=(C*1e6).toFixed(0);uVal.textContent=U;fVal.textContent=freq.toFixed(1);
  const{f0,Im,Q,df}=params(R,L,C,U);
  f0D.textContent=f0.toFixed(1);iMaxD.textContent=Im.toFixed(3);dfD.textContent=df.toFixed(1);qD.textContent=Q.toFixed(2);
  phiSpan.style.display='none';phaseModeSpan.style.display='none';
  const fMax=Math.max(200,f0*3),data=curve(R,L,C,U,1,fMax,150);
  ctx.clearRect(0,0,W,H);ctx.fillStyle='#0f172a';ctx.fillRect(0,0,W,H);
  const pd={t:12,r:40,b:28,l:50},pw=W-pd.l-pd.r,ph=H-pd.t-pd.b;
  ctx.fillStyle='#1e293b';ctx.fillRect(pd.l,pd.t,pw,ph);
  const maxI=Math.max(Im*1.3,0.01),maxZ=Math.max(data[0].Z*1.1,R*3);
  const toX=f=>pd.l+(f/fMax)*pw,toY_I=v=>pd.t+ph-(v/maxI)*ph,toY_Z=v=>pd.t+ph-(v/maxZ)*ph;
  ctx.strokeStyle='#334155';ctx.lineWidth=0.5;
  for(let i=0;i<=4;i++){const y=pd.t+(i/4)*ph;ctx.beginPath();ctx.moveTo(pd.l,y);ctx.lineTo(pd.l+pw,y);ctx.stroke()}
  for(let i=1;i<=4;i++){const x=pd.l+(i/4)*pw;ctx.beginPath();ctx.moveTo(x,pd.t);ctx.lineTo(x,pd.t+ph);ctx.stroke()}
  ctx.fillStyle='#64748b';ctx.font='8px sans-serif';ctx.textAlign='right';
  for(let i=0;i<=4;i++){const y=pd.t+(i/4)*ph;if(viewMode!=='z'){ctx.fillText((maxI*(1-i/4)).toFixed(2),pd.l-4,y+3)}}
  ctx.textAlign='center';
  for(let i=1;i<=4;i++){const x=pd.l+(i/4)*pw;ctx.fillText((fMax*i/4).toFixed(0),x,pd.t+ph+14)}
  ctx.fillStyle='#64748b';ctx.font='9px sans-serif';ctx.textAlign='center';ctx.fillText('f (Hz)',pd.l+pw/2,H-4);
  ctx.save();ctx.translate(12,pd.t+ph/2);ctx.rotate(-Math.PI/2);ctx.textAlign='center';ctx.fillText(viewMode==='z'?'Z (Ω)':'I (A)',0,0);ctx.restore();
  if(viewMode==='z'||viewMode==='both'){ctx.strokeStyle='#8b5cf6';ctx.lineWidth=1.5;ctx.setLineDash([4,3]);ctx.beginPath();for(let i=0;i<data.length;i++){const x=toX(data[i].f),y=toY_Z(data[i].Z);i===0?ctx.moveTo(x,y):ctx.lineTo(x,y)}ctx.stroke();ctx.setLineDash([]);if(viewMode==='both'){ctx.fillStyle='#8b5cf6';ctx.font='7px sans-serif';ctx.textAlign='left';ctx.fillText('Z',pd.l+pw+2,pd.t+8)}}
  if(viewMode==='i'||viewMode==='both'){ctx.strokeStyle='#ef4444';ctx.lineWidth=2.5;ctx.beginPath();for(let i=0;i<data.length;i++){const x=toX(data[i].f),y=toY_I(data[i].I);i===0?ctx.moveTo(x,y):ctx.lineTo(x,y)}ctx.stroke()}
  ctx.strokeStyle='#22c55e';ctx.lineWidth=1;ctx.setLineDash([4,2]);ctx.beginPath();const f0x=toX(f0);ctx.moveTo(f0x,pd.t);ctx.lineTo(f0x,pd.t+ph);ctx.stroke();ctx.setLineDash([]);
  ctx.fillStyle='#22c55e';ctx.font='bold 9px sans-serif';ctx.textAlign='center';ctx.fillText('f₀='+f0.toFixed(1)+' Hz',f0x,pd.t-4);
  if(viewMode!=='z'){const i0y=toY_I(Im);ctx.fillStyle='#fbbf24';ctx.beginPath();ctx.arc(f0x,i0y,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#000';ctx.beginPath();ctx.arc(f0x,i0y,2.5,0,Math.PI*2);ctx.fill()}
  if(viewMode!=='z'){const Ih=Im/Math.SQRT2,yH=toY_I(Ih);ctx.strokeStyle='rgba(139,92,246,0.5)';ctx.lineWidth=1;ctx.setLineDash([2,3]);ctx.beginPath();ctx.moveTo(pd.l,yH);ctx.lineTo(pd.l+pw,yH);ctx.stroke();ctx.setLineDash([]);let f1=f0,f2=f0;for(const pt of data){if(pt.I>=Ih-0.001&&pt.f<f0)f1=pt.f;if(pt.I>=Ih-0.001&&pt.f>f0){f2=pt.f;break}}ctx.fillStyle='#8b5cf6';ctx.font='7px sans-serif';ctx.textAlign='center';ctx.fillText('Δf='+(f2-f1).toFixed(1)+'Hz',toX((f1+f2)/2),yH-6);ctx.strokeStyle='#8b5cf6';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(toX(f1),yH);ctx.lineTo(toX(f2),yH);ctx.stroke()}
  const cur=compute(R,L,C,U,freq);const cx=toX(freq);ctx.fillStyle='#fbbf24';ctx.beginPath();ctx.arc(cx,toY_I(cur.I),4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fbbf24';ctx.font='8px sans-serif';ctx.textAlign='center';ctx.fillText(freq.toFixed(1)+' Hz',cx,pd.t+ph+4);
}
function drawTime(){
  const R=+rS.value,L=+lS.value,C=+cS.value*1e-6,U=+uS.value,freq=+fS.value;
  rVal.textContent=R;lVal.textContent=L.toFixed(2);cVal.textContent=(C*1e6).toFixed(0);uVal.textContent=U;fVal.textContent=freq.toFixed(1);
  const{f0}=params(R,L,C,U);f0D.textContent=f0.toFixed(1);
  phiSpan.style.display='inline';phaseModeSpan.style.display='none';
  ctx.clearRect(0,0,W,H);ctx.fillStyle='#0f172a';ctx.fillRect(0,0,W,H);
  const pd={t:12,r:10,b:28,l:50},pw=W-pd.l-pd.r,ph=H-pd.t-pd.b;
  ctx.fillStyle='#1e293b';ctx.fillRect(pd.l,pd.t,pw,ph);
  const tMax=Math.min(0.12,5/f0);
  const w=2*Math.PI*freq,w0=1/Math.sqrt(L*C),g=R/(2*L);
  const Xm=U/Math.sqrt((w0*w0-w*w)**2+(2*g*w)**2)*C;
  const phi=-Math.atan2(2*g*w,w0*w0-w*w);
  function qAna(t){return Xm*Math.cos(w*t+phi)}
  function iAna(t){return -Xm*w*Math.sin(w*t+phi)}
  function uAna(t){return -U*Math.cos(w*t)}
  const maxQ=Math.max(Xm*1.5,1e-6),maxI=Math.max(Xm*w*1.5,0.001),maxU=Math.max(U*1.5,1);
  const toX=t=>pd.l+(t/tMax)*pw,toY=(v,mx)=>pd.t+ph/2-(v/(mx*1.8))*ph/2;
  ctx.strokeStyle='#334155';ctx.lineWidth=0.5;
  for(let i=0;i<=4;i++){const y=pd.t+(i/4)*ph;ctx.beginPath();ctx.moveTo(pd.l,y);ctx.lineTo(pd.l+pw,y);ctx.stroke()}
  for(let i=1;i<=4;i++){const x=pd.l+(i/4)*pw;ctx.beginPath();ctx.moveTo(x,pd.t);ctx.lineTo(x,pd.t+ph);ctx.stroke()}
  ctx.fillStyle='#64748b';ctx.font='7px sans-serif';ctx.textAlign='right';
  ctx.fillText('q(max)',pd.l-4,pd.t+8);ctx.fillText('0',pd.l-4,pd.t+ph/2+3);ctx.fillText('-q(max)',pd.l-4,pd.t+ph-4);
  ctx.textAlign='center';ctx.fillStyle='#64748b';ctx.font='9px sans-serif';ctx.fillText('t (s)',pd.l+pw/2,H-4);
  ctx.strokeStyle='rgba(251,191,36,0.4)';ctx.lineWidth=1;ctx.setLineDash([3,3]);ctx.beginPath();
  for(let t=0;t<=tMax;t+=tMax/150){const x=toX(t),y=toY(uAna(t),maxU);t===0?ctx.moveTo(x,y):ctx.lineTo(x,y)}ctx.stroke();ctx.setLineDash([]);
  ctx.strokeStyle='#38bdf8';ctx.lineWidth=2.2;ctx.beginPath();
  for(let t=0;t<=tMax;t+=tMax/200){const x=toX(t),y=toY(qAna(t),maxQ);t===0?ctx.moveTo(x,y):ctx.lineTo(x,y)}ctx.stroke();
  ctx.strokeStyle='#22c55e';ctx.lineWidth=2;ctx.setLineDash([4,2]);ctx.beginPath();
  for(let t=0;t<=tMax;t+=tMax/200){const x=toX(t),y=toY(iAna(t),maxI);t===0?ctx.moveTo(x,y):ctx.lineTo(x,y)}ctx.stroke();ctx.setLineDash([]);
  const curX=toX(simT);ctx.strokeStyle='#f59e0b';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(curX,pd.t);ctx.lineTo(curX,pd.t+ph);ctx.stroke();
  const qc=qAna(simT),ic=iAna(simT);ctx.fillStyle='#38bdf8';ctx.beginPath();ctx.arc(curX,toY(qc,maxQ),3.5,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#22c55e';ctx.beginPath();ctx.arc(curX,toY(ic,maxI),3.5,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='rgba(251,191,36,0.7)';ctx.beginPath();ctx.arc(curX,toY(uAna(simT),maxU),2,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#64748b';ctx.font='7px sans-serif';ctx.textAlign='center';ctx.fillText('—— q(t)',pd.l+40,pd.t+10);ctx.fillStyle='#22c55e';ctx.fillText('- - - i(t)',pd.l+40,pd.t+18);ctx.fillStyle='rgba(251,191,36,0.6)';ctx.fillText('· · · u(t)',pd.l+40,pd.t+26);
  ctx.fillStyle='#fbbf24';ctx.font='8px sans-serif';ctx.textAlign='center';ctx.fillText('t='+(simT*1e3).toFixed(2)+' ms',curX,pd.t+ph+5);
  const phiDeg=-Math.atan2(2*g*w,w0*w0-w*w)*180/Math.PI;
  iMaxD.textContent=(Xm*w).toFixed(3);dfD.textContent=(R/(2*Math.PI*L)).toFixed(1);qD.textContent=(1/R)*Math.sqrt(L/C);phiD.textContent=phiDeg.toFixed(1);
}
function stepRK4(){
  const R=+rS.value,L=+lS.value,C=+cS.value*1e-6,U=+uS.value,freq=+fS.value;
  const w=2*Math.PI*freq;
  function dqdt(q,i,t){return i}
  function didt(q,i,t){return(U*Math.cos(w*t)-R*i-q/C)/L}
  const h=dt;
  const k1v=dqdt(simQ,simI,simT),k1a=didt(simQ,simI,simT);
  const k2v=dqdt(simQ+h/2*k1v,simI+h/2*k1a,simT+h/2),k2a=didt(simQ+h/2*k1v,simI+h/2*k1a,simT+h/2);
  const k3v=dqdt(simQ+h/2*k2v,simI+h/2*k2a,simT+h/2),k3a=didt(simQ+h/2*k2v,simI+h/2*k2a,simT+h/2);
  const k4v=dqdt(simQ+h*k3v,simI+h*k3a,simT+h),k4a=didt(simQ+h*k3v,simI+h*k3a,simT+h);
  simQ+=h/6*(k1v+2*k2v+2*k3v+k4v);simI+=h/6*(k1a+2*k2a+2*k3a+k4a);simT+=h;
  const f0=1/(2*Math.PI*Math.sqrt(L*C));
  if(simT>0.1||simT>5/f0)simT=0;
}
function animateTime(){
  if(!timePlaying)return;
  for(let s=0;s<Math.round(speed*3);s++)stepRK4();
  drawTime();
  timeAnim=requestAnimationFrame(animateTime);
}
function toggleTimePlay(){
  timePlaying=!timePlaying;playTimeBtn.textContent=timePlaying?'⏸':'▶ زمني';playTimeBtn.style.background=timePlaying?'#ef4444':'#166534';playTimeBtn.style.color=timePlaying?'#fff':'#86efac';playTimeBtn.style.borderColor=timePlaying?'#ef4444':'#22c55e';
  if(timePlaying)animateTime();else if(timeAnim){cancelAnimationFrame(timeAnim);timeAnim=null}
}
function toggleSweep(){
  isSweeping=!isSweeping;playFreqBtn.textContent=isSweeping?'⏸ إيقاف':'▶ مسح ترددي';playFreqBtn.style.background=isSweeping?'#ef4444':'#3b82f6';
  if(isSweeping)animSweep();else if(window.sweepAnim){cancelAnimationFrame(window.sweepAnim);window.sweepAnim=null}
}
function animSweep(){
  if(!isSweeping)return;let v=+fS.value+0.5*speed;if(v>200){v=200;toggleSweep()}fS.value=v;drawFreq();window.sweepAnim=requestAnimationFrame(animSweep);
}
speedBtns.forEach(b=>b.addEventListener('click',()=>{
  speedBtns.forEach(x=>x.classList.remove('active'));b.classList.add('active');speed=+b.dataset.speed;
}));
viewBtns.forEach(b=>b.addEventListener('click',()=>{
  if(viewMode==='time'&&timePlaying)toggleTimePlay();
  viewBtns.forEach(x=>x.classList.remove('active'));b.classList.add('active');viewMode=b.dataset.view;
  document.getElementById('fLabel').textContent=viewMode==='time'?'تردد المثير f:':'التردد f:';
  if(viewMode==='phi')drawPhi();else if(viewMode==='time'){simT=0;drawTime()}else drawFreq();
}));
playFreqBtn.addEventListener('click',()=>{if(timePlaying)toggleTimePlay();toggleSweep()});
playTimeBtn.addEventListener('click',()=>{if(isSweeping)toggleSweep();toggleTimePlay()});
resetBtn.addEventListener('click',()=>{
  if(isSweeping)toggleSweep();if(timePlaying)toggleTimePlay();
  rS.value='100';lS.value='0.50';cS.value='20';uS.value='12';fS.value='50.3';simT=0;simQ=0;simI=0;
  if(viewMode==='phi')drawPhi();else if(viewMode==='time')drawTime();else drawFreq();
});
[rS,lS,cS,uS].forEach(s=>s.addEventListener('input',()=>{if(isSweeping)toggleSweep();if(timePlaying)toggleTimePlay();simT=0;simQ=0;simI=0;if(viewMode==='phi')drawPhi();else if(viewMode==='time')drawTime();else drawFreq()}));
