.container{max-width:700px;width:100%;margin:0 auto}
h1{text-align:center;font-size:14px;color:#fbbf24;margin-bottom:3px}
h2{text-align:center;font-size:10px;color:#64748b;margin-bottom:4px;font-weight:400}
canvas#mainCanvas{display:block;margin:0 auto;width:100%;max-width:680px;height:380px;background:#0f172a;border:1px solid #334155;border-radius:8px}
