const cv=document.getElementById('mainCanvas'),cx=cv.getContext('2d');
const W=680,H=380;
const mS=document.getElementById('mSld'),kS=document.getElementById('kSld'),hS=document.getElementById('hSld'),fmS=document.getElementById('fmSld'),wfS=document.getElementById('wfSld');
const speedBtns=document.querySelectorAll('.speed-btn'),viewBtns=document.querySelectorAll('[data-view]');
const playBtn=document.getElementById('playTimeBtn'),resetBtn=document.getElementById('resetBtn');
const mD=document.getElementById('mVal'),kD=document.getElementById('kVal'),hD=document.getElementById('hVal'),fmD=document.getElementById('fmVal'),wfD=document.getElementById('wfVal'),wfL=document.getElementById('wfLabel');
const w0D=document.getElementById('w0D'),xmD=document.getElementById('xmD'),phiD=document.getElementById('phiD'),qD=document.getElementById('qD'),dwD=document.getElementById('dwD');
let speed=1,viewMode='time',timePlaying=false,animId=null;
let simX=0,simV=0,simT=0,dt=5e-4;
let xHist=[],tHist=[],maxHist=300;

function getPars(){
  const m=+mS.value,k=+kS.value,h=+hS.value,Fm=+fmS.value,r=+wfS.value;
  const w0=Math.sqrt(k/m),w=r*w0,g=h/(2*m);
  return{m,k,h,Fm,r,w0,w,g};
}

function XmSS(p){
  const{k,m,Fm,w0,w,g}=p;
  return Fm/Math.sqrt((k-m*w*w)**2+(2*m*g*w)**2);
}

function phiSS(p){
  const{k,m,w,g}=p;
  return -Math.atan2(2*m*g*w,k-m*w*w);
}

function stepRK4(){
  const p=getPars();
  const m=p.m,k=p.k,Fm=p.Fm,w=p.w;
  const h=dt;
  function dxdt(x,v,t){return v}
  function dvdt(x,v,t){return(Fm*Math.cos(w*t)-k*x-p.h*v)/m}
  const k1v=dxdt(simX,simV,simT),k1a=dvdt(simX,simV,simT);
  const k2v=dxdt(simX+h/2*k1v,simV+h/2*k1a,simT+h/2),k2a=dvdt(simX+h/2*k1v,simV+h/2*k1a,simT+h/2);
  const k3v=dxdt(simX+h/2*k2v,simV+h/2*k2a,simT+h/2),k3a=dvdt(simX+h/2*k2v,simV+h/2*k2a,simT+h/2);
  const k4v=dxdt(simX+h*k3v,simV+h*k3a,simT+h),k4a=dvdt(simX+h*k3v,simV+h*k3a,simT+h);
  simX+=h/6*(k1v+2*k2v+2*k3v+k4v);simV+=h/6*(k1a+2*k2a+2*k3a+k4a);simT+=h;
  const T=2*Math.PI/p.w;
  if(simT>2||simT>8*T)simT=0;
}

function drawMech(){
  const p=getPars();const m=p.m,Fm=p.Fm,w=p.w,w0=p.w0;
  mD.textContent=m.toFixed(1);kD.textContent=p.k.toFixed(0);hD.textContent=p.h.toFixed(1);fmD.textContent=Fm.toFixed(1);wfD.textContent=p.r.toFixed(2);
  const Xm=XmSS(p),phi=phiSS(p);
  xmD.textContent=Xm.toFixed(3);phiD.textContent=(phi*180/Math.PI).toFixed(1);qD.textContent=(Math.sqrt(p.k*m)/p.h).toFixed(2);dwD.textContent=(p.h/m).toFixed(3);w0D.textContent=w0.toFixed(2);
  cx.clearRect(0,0,W,H);cx.fillStyle='#0f172a';cx.fillRect(0,0,W,H);
  const dW=240,dX=dW+10,dP=W-dX-15;
  const pd={t:12,r:8,b:28,l:10},pw=dP-pd.l-pd.r,ph=H-pd.t-pd.b;
  const mx=Math.max(210,dW);

  // ── Mechanical visual ──
  if(viewMode==='time'||viewMode==='both'){
    const cy=150,baseX=120;
    const x0=baseX,y0=cy-60;
    const disp=simX*30;
    // Support
    cx.fillStyle='#475569';cx.fillRect(x0-60,y0-5,120,4);
    // Spring
    cx.strokeStyle='#94a3b8';cx.lineWidth=2;
    cx.beginPath();const nCoils=8;const sTop=y0,sBot=cy-25;
    for(let i=0;i<=nCoils;i++){
      const t=i/nCoils;const yy=sTop+t*(sBot-sTop);
      const xx=x0+disp+((i%2===0)?-12:12)*(1-t*0.3);
      i===0?cx.moveTo(xx,yy):cx.lineTo(xx,yy);
    }
    cx.stroke();
    // Damper
    cx.strokeStyle='#94a3b8';cx.lineWidth=2;
    const dy=cy-20;cx.fillStyle='#475569';
    cx.fillRect(x0+disp-18,dy,36,22);
    cx.strokeRect(x0+disp-18,dy,36,22);
    cx.beginPath();cx.moveTo(x0+disp,dy);cx.lineTo(x0+disp,dy+22);cx.stroke();
    cx.beginPath();cx.moveTo(x0+disp-8,dy+6);cx.lineTo(x0+disp+8,dy+6);cx.stroke();
    cx.beginPath();cx.moveTo(x0+disp-8,dy+16);cx.lineTo(x0+disp+8,dy+16);cx.stroke();
    // Mass block
    const mw=Math.max(20,Math.min(50,8+m*6));
    cx.fillStyle='#3b82f6';cx.fillRect(x0+disp-mw/2,cy-12,mw,24);
    cx.strokeStyle='#60a5fa';cx.lineWidth=1;cx.strokeRect(x0+disp-mw/2,cy-12,mw,24);
    cx.fillStyle='#fff';cx.font='bold 8px sans-serif';cx.textAlign='center';cx.fillText('m',x0+disp,cy+4);
    // Ground
    const gy=cy+25;cx.fillStyle='#334155';cx.fillRect(x0-80,gy,160,3);
    // F(t) arrow
    const fScale=Math.min(1,Fm/30);
    const fx=x0+disp+40+30*fScale;
    cx.strokeStyle='#ef4444';cx.lineWidth=2.5;
    cx.beginPath();cx.moveTo(x0+disp+40,cy);cx.lineTo(fx,cy);cx.stroke();
    cx.beginPath();cx.moveTo(fx,cy);cx.lineTo(fx-8,cy-5);cx.lineTo(fx-8,cy+5);cx.closePath();cx.fillStyle='#ef4444';cx.fill();
    cx.fillStyle='#ef4444';cx.font='bold 8px sans-serif';cx.textAlign='center';cx.fillText('F(t)',x0+disp+25,cy-12);
    cx.fillStyle='#64748b';cx.font='7px sans-serif';cx.textAlign='right';
    cx.fillText('k='+p.k.toFixed(0),x0-5,y0-8);
    cx.fillText('h='+p.h.toFixed(1),x0-5,cy-5);
    // Axis labels below
    cx.fillStyle='#94a3b8';cx.font='7px sans-serif';cx.textAlign='center';
    cx.fillText('ω/ω₀='+p.r.toFixed(2),x0,gy+12);
    cx.fillText('t='+(simT).toFixed(2)+'s',x0,gy+20);
  }

  // ── Plots ──
  const T0=2*Math.PI/w0;
  const showBoth=viewMode==='both';
  const plotL=dW+10+(showBoth?10:0);
  const plotR=W-(showBoth?10:15);
  const plotW=plotR-plotL;
  const plotH=showBoth?Math.floor((H-pd.t-pd.b-4)/2):H-pd.t-pd.b;
  const pTop=pd.t;

  if(viewMode==='time'||viewMode==='both'){
    const p1H=showBoth?plotH:H-pd.t-pd.b;
    const tMax=Math.max(2,6*T0);
    const xSS=XmSS(p);
    const maxA=Math.max(Math.abs(xSS)*1.5,0.01);
    const toX=t=>plotL+(t/tMax)*plotW;
    const toY=v=>pTop+p1H/2-(v/maxA)*p1H/2;
    // Background
    cx.fillStyle='#1e293b';cx.fillRect(plotL,pTop,plotW,p1H);
    cx.strokeStyle='#334155';cx.lineWidth=0.5;
    for(let i=0;i<=4;i++){const y=pTop+(i/4)*p1H;cx.beginPath();cx.moveTo(plotL,y);cx.lineTo(plotR,y);cx.stroke()}
    for(let i=1;i<=4;i++){const x=plotL+(i/4)*plotW;cx.beginPath();cx.moveTo(x,pTop);cx.lineTo(x,pTop+p1H);cx.stroke()}
    // Envelope
    const env=XmSS(p);
    if(env>0.001){cx.strokeStyle='rgba(255,255,255,0.1)';cx.lineWidth=0.5;cx.setLineDash([3,3]);cx.beginPath();for(let t=0;t<=tMax;t+=tMax/100){const y=toY(env);t===0?cx.moveTo(toX(t),y):cx.lineTo(toX(t),y)}cx.stroke();cx.beginPath();for(let t=0;t<=tMax;t+=tMax/100){const y=toY(-env);t===0?cx.moveTo(toX(t),y):cx.lineTo(toX(t),y)}cx.stroke();cx.setLineDash([])}
    // Steady-state x(t)
    cx.strokeStyle='#38bdf8';cx.lineWidth=2;cx.beginPath();
    for(let t=0;t<=tMax;t+=tMax/200){
      const p=getPars();const X=XmSS(p),ph=phiSS(p);
      const xv=X*Math.cos(p.w*t+ph);
      const x=toX(t),y=toY(xv);t===0?cx.moveTo(x,y):cx.lineTo(x,y);
    }cx.stroke();
    // Cursor
    const curX=toX(simT);cx.strokeStyle='#f59e0b';cx.lineWidth=1.5;cx.beginPath();cx.moveTo(curX,pTop);cx.lineTo(curX,pTop+p1H);cx.stroke();
    const xAn=p.w*simT+phiSS(p);const xCur=XmSS(p)*Math.cos(xAn);
    cx.fillStyle='#f59e0b';cx.beginPath();cx.arc(curX,toY(xCur),4,0,Math.PI*2);cx.fill();
    // Labels
    cx.fillStyle='#64748b';cx.font='7px sans-serif';cx.textAlign='left';
    if(!showBoth){cx.fillText('x(t)',plotL+4,pTop+10);cx.fillStyle='#94a3b8';cx.font='7px sans-serif';cx.textAlign='center';cx.fillText('t (s)',plotL+plotW/2,pTop+p1H+13)}
  }

  if(viewMode==='freq'||viewMode==='both'){
    const py=showBoth?pTop+plotH+4:pd.t;
    const ph2=showBoth?plotH:H-pd.t-pd.b;
    const fMax=3.5;
    const toX=r=>plotL+(r/fMax)*plotW;
    const pts=[];
    let maxX=0;
    for(let i=0;i<=200;i++){const r=(i/200)*fMax;const pp=getPars();pp.w=pp.w0*r;const xv=XmSS(pp);pts.push({r,xv});if(xv>maxX)maxX=xv}
    maxX=Math.max(maxX*1.2,0.01);
    const toY=v=>py+ph2-(v/maxX)*ph2;
    cx.fillStyle='#1e293b';cx.fillRect(plotL,py,plotW,ph2);
    cx.strokeStyle='#334155';cx.lineWidth=0.5;
    for(let i=0;i<=4;i++){const y=py+(i/4)*ph2;cx.beginPath();cx.moveTo(plotL,y);cx.lineTo(plotR,y);cx.stroke()}
    for(let i=1;i<=4;i++){const x=plotL+(i/4)*plotW;const rv=(i/4)*fMax;cx.beginPath();cx.moveTo(x,py);cx.lineTo(x,py+ph2);cx.stroke()}
    // Labels
    cx.fillStyle='#64748b';cx.font='7px sans-serif';cx.textAlign='center';
    if(!showBoth){for(let i=1;i<=4;i++){const x=plotL+(i/4)*plotW;cx.fillText((i/4*fMax).toFixed(1),x,py+ph2+11)}}
    cx.fillStyle='#94a3b8';cx.font='7px sans-serif';cx.textAlign='center';cx.fillText('ω/ω₀',plotL+plotW/2,py+ph2+11);
    // X_m curve
    cx.strokeStyle='#38bdf8';cx.lineWidth=2.5;cx.beginPath();
    for(let i=0;i<pts.length;i++){const x=toX(pts[i].r),y=toY(pts[i].xv);i===0?cx.moveTo(x,y):cx.lineTo(x,y)}cx.stroke();
    // f0 marker
    const f0x=toX(1);cx.strokeStyle='#22c55e';cx.lineWidth=1;cx.setLineDash([4,2]);cx.beginPath();cx.moveTo(f0x,py);cx.lineTo(f0x,py+ph2);cx.stroke();cx.setLineDash([]);
    cx.fillStyle='#22c55e';cx.font='bold 7px sans-serif';cx.textAlign='center';cx.fillText('ω₀',f0x,py-3);
    // Current ω marker
    const curR=+wfS.value;const curXv=toX(curR);const curYv=toY(XmSS(getPars()));
    cx.fillStyle='#fbbf24';cx.beginPath();cx.arc(curXv,curYv,4,0,Math.PI*2);cx.fill();
    cx.fillStyle='#fbbf24';cx.font='7px sans-serif';cx.textAlign='center';cx.fillText(p.r.toFixed(2),curXv,py+ph2-3);
    // Bandwidth
    const Ih=maxX/2;const yH=toY(Ih);cx.strokeStyle='rgba(139,92,246,0.5)';cx.lineWidth=1;cx.setLineDash([2,3]);cx.beginPath();cx.moveTo(plotL,yH);cx.lineTo(plotR,yH);cx.stroke();cx.setLineDash([]);
    // Labels when solo
    if(!showBoth){cx.fillStyle='#64748b';cx.font='7px sans-serif';cx.textAlign='left';cx.fillText('X_m (m)',plotL+4,py+10)}
  }
}

function resetAll(){
  if(timePlaying){timePlaying=false;if(animId){cancelAnimationFrame(animId);animId=null}playBtn.textContent='▶ زمني';playBtn.className='btn green'}
  mS.value='1';kS.value='50';hS.value='2';fmS.value='10';wfS.value='0.5';
  simX=0;simV=0;simT=0;
  drawMech();
}

function toggleTime(){
  timePlaying=!timePlaying;
  playBtn.textContent=timePlaying?'⏸ إيقاف':'▶ زمني';
  playBtn.className=timePlaying?'btn red':'btn green';
  if(timePlaying)animStep();else if(animId){cancelAnimationFrame(animId);animId=null}
}

function animStep(){
  if(!timePlaying)return;
  for(let s=0;s<Math.round(speed*4);s++)stepRK4();
  drawMech();
  animId=requestAnimationFrame(animStep);
}

speedBtns.forEach(b=>b.addEventListener('click',()=>{
  speedBtns.forEach(x=>x.classList.remove('active'));b.classList.add('active');speed=+b.dataset.speed;
}));

viewBtns.forEach(b=>b.addEventListener('click',()=>{
  if(timePlaying)toggleTime();
  viewBtns.forEach(x=>x.classList.remove('active'));b.classList.add('active');viewMode=b.dataset.view;
  drawMech();
}));

playBtn.addEventListener('click',toggleTime);
resetBtn.addEventListener('click',resetAll);
[mS,kS,hS,fmS,wfS].forEach(s=>s.addEventListener('input',()=>{
  if(timePlaying)toggleTime();simX=0;simV=0;simT=0;drawMech();
}));

drawMech();
